package redis

import (
	"context"
	"fmt"
	"slices"
	"sync"
	"testing"
	"time"

	"github.com/google/uuid"
	"github.com/redis/go-redis/v9"
	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"

	"github.com/e2b-dev/infra/packages/api/internal/sandbox/sandboxtypes"
)

// mgetRecorder is a go-redis hook that records the key count of every MGET the
// client sends, including MGETs inside pipelines.
type mgetRecorder struct {
	mu        sync.Mutex
	keyCounts []int
}

func (r *mgetRecorder) record(cmd redis.Cmder) {
	if cmd.Name() != "mget" {
		return
	}
	r.mu.Lock()
	defer r.mu.Unlock()
	// args = ["mget", key1, key2, ...]
	r.keyCounts = append(r.keyCounts, len(cmd.Args())-1)
}

func (r *mgetRecorder) reset() {
	r.mu.Lock()
	defer r.mu.Unlock()
	r.keyCounts = nil
}

func (r *mgetRecorder) snapshot() []int {
	r.mu.Lock()
	defer r.mu.Unlock()

	return append([]int(nil), r.keyCounts...)
}

func (r *mgetRecorder) DialHook(next redis.DialHook) redis.DialHook {
	return next
}

func (r *mgetRecorder) ProcessHook(next redis.ProcessHook) redis.ProcessHook {
	return func(ctx context.Context, cmd redis.Cmder) error {
		r.record(cmd)

		return next(ctx, cmd)
	}
}

func (r *mgetRecorder) ProcessPipelineHook(next redis.ProcessPipelineHook) redis.ProcessPipelineHook {
	return func(ctx context.Context, cmds []redis.Cmder) error {
		for _, cmd := range cmds {
			r.record(cmd)
		}

		return next(ctx, cmds)
	}
}

// TestReconcile_SpansSeveralBatches pins that Reconcile classifies every node
// sandbox correctly when one team's candidates are split across several MGET
// commands: each result has to line up with the candidate it was fetched for,
// or a live sandbox in one chunk would be reported as an orphan from another.
//
// It also asserts the chunking itself through a client hook: the number of
// MGETs sent, that none carries more than sandboxScanBatchSize keys, and that
// the key counts add up to the candidate count. The orphan-set check alone
// passes with a single unbounded MGET, so without this a revert of the
// chunking would go unnoticed.
func TestReconcile_SpansSeveralBatches(t *testing.T) {
	t.Parallel()

	storage, client := setupTestStorage(t)
	teamID := uuid.New()
	started := time.Now().Add(-2 * orphanGracePeriod)

	rec := &mgetRecorder{}
	client.AddHook(rec)

	// More than two full chunks plus a partial one, all in the store.
	stored := sandboxScanBatchSize*2 + 37
	seedTeamSandboxes(t, client, teamID, stored, sandboxtypes.StateRunning)

	var nodeSandboxes []sandboxtypes.NodeSandbox
	for i := range stored {
		nodeSandboxes = append(nodeSandboxes, sandboxtypes.NodeSandbox{
			SandboxID: fmt.Sprintf("sbx-%s-%04d", sandboxtypes.StateRunning, i),
			TeamID:    teamID,
			StartTime: started,
		})
	}

	// Orphans the node reports but the store never saw, placed so that they
	// land in the first, a middle, and the final chunk.
	orphanIDs := []string{"orphan-first", "orphan-middle", "orphan-last"}
	orphans := []sandboxtypes.NodeSandbox{
		{SandboxID: orphanIDs[0], TeamID: teamID, StartTime: started},
		{SandboxID: orphanIDs[1], TeamID: teamID, StartTime: started},
		{SandboxID: orphanIDs[2], TeamID: teamID, StartTime: started},
	}
	nodeSandboxes = slices.Insert(nodeSandboxes, 0, orphans[0])
	nodeSandboxes = slices.Insert(nodeSandboxes, sandboxScanBatchSize+10, orphans[1])
	nodeSandboxes = append(nodeSandboxes, orphans[2])

	// Too young to be judged, even though it is not in the store.
	nodeSandboxes = append(nodeSandboxes, sandboxtypes.NodeSandbox{
		SandboxID: "fresh-not-yet-stored",
		TeamID:    teamID,
		StartTime: time.Now(),
	})

	// Seeding does not MGET, but reset so the assertions below see only what
	// Reconcile sent.
	rec.reset()

	got := storage.Reconcile(t.Context(), nodeSandboxes, "test-node")

	gotIDs := make([]string, 0, len(got))
	for _, sbx := range got {
		gotIDs = append(gotIDs, sbx.SandboxID)
	}
	require.ElementsMatch(t, orphanIDs, gotIDs, "exactly the stored-nowhere, old-enough sandboxes are orphans")
	for _, sbx := range got {
		assert.Equal(t, teamID, sbx.TeamID)
	}

	// Candidates = stored + 3 orphans; the fresh one is filtered before any
	// read. 552 keys / 256 per command = 3 commands: 256, 256, 40.
	candidates := stored + len(orphans)
	counts := rec.snapshot()
	wantCmds := (candidates + sandboxScanBatchSize - 1) / sandboxScanBatchSize
	require.Len(t, counts, wantCmds, "MGET commands sent: %v", counts)
	sum := 0
	for _, n := range counts {
		require.LessOrEqual(t, n, sandboxScanBatchSize, "an MGET exceeded the per-command key cap: %v", counts)
		sum += n
	}
	require.Equal(t, candidates, sum, "MGET key counts should cover every candidate exactly once: %v", counts)
}

package main

import (
	"context"
	"net/http"
	"testing"

	"github.com/google/uuid"
	"github.com/stretchr/testify/require"

	"github.com/e2b-dev/infra/packages/dashboard-api/internal/cfg"
	"github.com/e2b-dev/infra/packages/dashboard-api/internal/identity"
	"github.com/e2b-dev/infra/packages/shared/pkg/logger"
)

// emptyLinkage answers "this user has no linked identity", which is all the
// configured branch needs: it never reaches the identity provider.
type emptyLinkage struct{}

func (emptyLinkage) IdentitiesForUsers(_ context.Context, _ []string, _ []uuid.UUID) ([]identity.LinkedIdentity, error) {
	return nil, nil
}

func TestNewIdentityServiceWithoutOryIsUnavailable(t *testing.T) {
	t.Parallel()

	service, err := newIdentityService(t.Context(), logger.NewNopLogger(), cfg.Config{}, http.DefaultClient, emptyLinkage{})
	require.NoError(t, err)

	_, err = service.ProfilesByUserID(t.Context(), []uuid.UUID{uuid.New()})
	require.ErrorIs(t, err, identity.ErrNoIdentityProvider)
}

func TestNewIdentityServiceWithOryIsBacked(t *testing.T) {
	t.Parallel()

	config := cfg.Config{
		OrySDKURL:          "https://tenant.projects.oryapis.com",
		OryProjectAPIToken: "pat",
	}

	service, err := newIdentityService(t.Context(), logger.NewNopLogger(), config, http.DefaultClient, emptyLinkage{})
	require.NoError(t, err)

	profiles, err := service.ProfilesByUserID(t.Context(), []uuid.UUID{uuid.New()})
	require.NoError(t, err)
	require.Empty(t, profiles)
}

package identity

import (
	"context"
	"testing"

	"github.com/google/uuid"
)

type fakeDirectory struct {
	identities map[string]Identity

	listErr     error
	listedBatch [][]string
}

func newFakeDirectory(identities ...Identity) *fakeDirectory {
	byID := make(map[string]Identity, len(identities))
	for _, id := range identities {
		byID[id.Subject] = id
	}

	return &fakeDirectory{identities: byID}
}

func (d *fakeDirectory) ListIdentities(_ context.Context, subjects []string) ([]Identity, error) {
	d.listedBatch = append(d.listedBatch, subjects)
	if d.listErr != nil {
		return nil, d.listErr
	}

	found := make([]Identity, 0, len(subjects))
	for _, subject := range subjects {
		if id, ok := d.identities[subject]; ok {
			found = append(found, id)
		}
	}

	return found, nil
}

type fakeLinkage struct {
	rows []LinkedIdentity

	requestedIssuers []string
}

func (l *fakeLinkage) IdentitiesForUsers(_ context.Context, issuers []string, userIDs []uuid.UUID) ([]LinkedIdentity, error) {
	l.requestedIssuers = issuers

	allowed := make(map[string]struct{}, len(issuers))
	for _, issuer := range issuers {
		allowed[issuer] = struct{}{}
	}
	wanted := make(map[uuid.UUID]struct{}, len(userIDs))
	for _, id := range userIDs {
		wanted[id] = struct{}{}
	}

	matched := make([]LinkedIdentity, 0, len(l.rows))
	for _, row := range l.rows {
		if _, ok := allowed[row.Issuer]; !ok {
			continue
		}
		if _, ok := wanted[row.UserID]; !ok {
			continue
		}
		matched = append(matched, row)
	}

	return matched, nil
}

const (
	issuerA = "https://issuer-a.example.test"
	issuerB = "https://issuer-b.example.test"
)

func TestNewServiceValidatesInput(t *testing.T) {
	t.Parallel()

	if _, err := NewService(nil, &fakeLinkage{}); err == nil {
		t.Fatal("expected error for empty directory registry")
	}
	if _, err := NewService(map[string]Directory{issuerA: newFakeDirectory()}, nil); err == nil {
		t.Fatal("expected error for nil linkage")
	}
	if _, err := NewService(map[string]Directory{" ": newFakeDirectory()}, &fakeLinkage{}); err == nil {
		t.Fatal("expected error for blank issuer")
	}
	if _, err := NewService(map[string]Directory{issuerA: nil}, &fakeLinkage{}); err == nil {
		t.Fatal("expected error for nil directory")
	}
}

func TestServiceProfilesByUserIDRoutesAcrossIssuers(t *testing.T) {
	t.Parallel()

	userA := uuid.New()
	userB := uuid.New()
	subjectA := uuid.NewString()
	subjectB := uuid.NewString()

	directoryA := newFakeDirectory(Identity{Subject: subjectA, Email: "a@example.test"})
	directoryB := newFakeDirectory(Identity{Subject: subjectB, Email: "b@example.test"})
	linkage := &fakeLinkage{rows: []LinkedIdentity{
		{Issuer: issuerA, Subject: subjectA, UserID: userA},
		{Issuer: issuerB, Subject: subjectB, UserID: userB},
	}}

	svc, err := NewService(map[string]Directory{issuerA: directoryA, issuerB: directoryB}, linkage)
	if err != nil {
		t.Fatalf("failed to build service: %v", err)
	}

	profiles, err := svc.ProfilesByUserID(t.Context(), []uuid.UUID{userA, userB})
	if err != nil {
		t.Fatalf("ProfilesByUserID returned error: %v", err)
	}

	if len(profiles) != 2 {
		t.Fatalf("expected 2 profiles, got %d", len(profiles))
	}
	if profiles[userA].Email != "a@example.test" {
		t.Fatalf("expected profile for user A from issuer A, got %+v", profiles[userA])
	}
	if profiles[userB].Email != "b@example.test" {
		t.Fatalf("expected profile for user B from issuer B, got %+v", profiles[userB])
	}
	if len(linkage.requestedIssuers) != 2 {
		t.Fatalf("expected linkage lookup filtered to both registered issuers, got %v", linkage.requestedIssuers)
	}
}

func TestServiceUserKeyedOpsIgnoreUnregisteredIssuerRows(t *testing.T) {
	t.Parallel()

	userID := uuid.New()
	linkage := &fakeLinkage{rows: []LinkedIdentity{
		{Issuer: "https://foreign.example.test", Subject: uuid.NewString(), UserID: userID},
	}}

	svc, err := NewService(map[string]Directory{issuerA: newFakeDirectory()}, linkage)
	if err != nil {
		t.Fatalf("failed to build service: %v", err)
	}

	profiles, err := svc.ProfilesByUserID(t.Context(), []uuid.UUID{userID})
	if err != nil {
		t.Fatalf("ProfilesByUserID returned error: %v", err)
	}
	if len(profiles) != 0 {
		t.Fatalf("expected foreign-issuer rows to be invisible, got %d profiles", len(profiles))
	}
}

package redis

import (
	"context"
	"encoding/json"
	"testing"
	"time"

	"github.com/google/uuid"
	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"

	"github.com/e2b-dev/infra/packages/api/internal/sandbox/sandboxtypes"
)

// A sandbox ID is reused across incarnations: kill or pause a sandbox, resume
// it, and the ID comes back attached to a new execution — potentially on a
// different node. A caller that decided from a snapshot taken earlier can
// therefore have its removal land on a sandbox that was never in scope.
//
// Eviction already guards its own version of this, by re-checking expiry under
// the storage lock: the evictor reads the expired set and then removes, so its
// decision can go stale in between. These tests pin the general form of that
// guard, for callers whose staleness is not expiry-shaped. Enforced under the
// same lock, because that is the only place the check cannot be raced.

func TestStartRemoving_ExecutionPinMismatchRefuses(t *testing.T) {
	t.Parallel()

	storage, _ := setupTestStorage(t)

	sbx := createTestSandbox("sbx-replaced")
	require.NoError(t, storage.Add(t.Context(), sbx))

	_, _, finish, err := storage.StartRemoving(t.Context(), sbx.TeamID, sbx.SandboxID, sandboxtypes.RemoveOpts{
		Action:            sandboxtypes.StateActionKill,
		Reason:            sandboxtypes.KillReasonRequest,
		ExpectExecutionID: uuid.NewString(), // the incarnation the caller saw, now gone
	})
	require.ErrorIs(t, err, sandboxtypes.ErrExecutionMismatch)
	require.Nil(t, finish, "a refused removal must not hand back a transition to finish")

	// The stored sandbox must be untouched — no state transition, still usable.
	stored, err := storage.Get(t.Context(), sbx.TeamID, sbx.SandboxID)
	require.NoError(t, err)
	assert.Equal(t, sandboxtypes.StateRunning, stored.State, "a refused removal must not transition the live sandbox")
	assert.Equal(t, sbx.ExecutionID, stored.ExecutionID)
}

func TestStartRemoving_ExecutionPinMatchProceeds(t *testing.T) {
	t.Parallel()

	storage, _ := setupTestStorage(t)

	sbx := createTestSandbox("sbx-still-there")
	require.NoError(t, storage.Add(t.Context(), sbx))

	_, alreadyDone, finish, err := storage.StartRemoving(t.Context(), sbx.TeamID, sbx.SandboxID, sandboxtypes.RemoveOpts{
		Action:            sandboxtypes.StateActionKill,
		Reason:            sandboxtypes.KillReasonRequest,
		ExpectExecutionID: sbx.ExecutionID,
	})
	require.NoError(t, err)
	require.False(t, alreadyDone)
	require.NotNil(t, finish)
	finish(t.Context(), nil)

	stored, err := storage.Get(t.Context(), sbx.TeamID, sbx.SandboxID)
	require.NoError(t, err)
	assert.Equal(t, sandboxtypes.StateKilling, stored.State)
}

// TestStartRemoving_ExecutionPinSurvivesWaitingOutATransition covers the retry
// path, which is where the pin matters most and is easiest to lose.
//
// When another transition is already in flight, the removal releases the lock,
// waits for it, and then retries itself. That wait is precisely the window in
// which the sandbox can finish pausing and be resumed under a new incarnation,
// so a retry that forgot the caller's pin would act on exactly the record the
// pin exists to protect.
func TestStartRemoving_ExecutionPinSurvivesWaitingOutATransition(t *testing.T) {
	t.Parallel()

	storage, _ := setupTestStorage(t)
	ctx := t.Context()

	sbx := createTestSandbox("sbx-pinned-through-wait")
	require.NoError(t, storage.Add(ctx, sbx))

	// Occupy the transition slot with a pause, so a kill cannot proceed
	// directly and has to wait it out and retry.
	_, _, finishPause, err := storage.StartRemoving(ctx, sbx.TeamID, sbx.SandboxID, sandboxtypes.RemoveOpts{
		Action: sandboxtypes.StateActionPause,
	})
	require.NoError(t, err)
	require.NotNil(t, finishPause)

	type outcome struct {
		finish func(context.Context, error)
		err    error
	}
	done := make(chan outcome, 1)

	// A kill pinned to the incarnation that is stored right now, so it clears
	// the pin check on the way in and blocks in the wait. The retry afterwards
	// is what this test is about.
	go func() {
		_, _, finish, err := storage.StartRemoving(ctx, sbx.TeamID, sbx.SandboxID, sandboxtypes.RemoveOpts{
			Action:            sandboxtypes.StateActionKill,
			Reason:            sandboxtypes.KillReasonRequest,
			ExpectExecutionID: sbx.ExecutionID,
		})
		done <- outcome{finish: finish, err: err}
	}()

	// Give the kill time to reach the wait, then do to the record what a resume
	// does: same sandbox ID, new incarnation. Completing a pause only touches
	// the transition key, so this write survives it.
	time.Sleep(100 * time.Millisecond)

	resumed := sbx
	resumed.ExecutionID = uuid.NewString()
	resumed.State = sandboxtypes.StateRunning
	writeTeamSandbox(t, storage, resumed)

	finishPause(ctx, nil)

	select {
	case got := <-done:
		require.ErrorIs(t, got.err, sandboxtypes.ErrExecutionMismatch,
			"a removal that waited out a transition must still honour its pin on retry")
		require.Nil(t, got.finish)
	case <-time.After(30 * time.Second):
		t.Fatal("pinned kill never returned after the in-flight transition completed")
	}

	// The resumed incarnation was never in scope and must be untouched.
	stored, err := storage.Get(ctx, sbx.TeamID, sbx.SandboxID)
	require.NoError(t, err)
	assert.Equal(t, resumed.ExecutionID, stored.ExecutionID)
	assert.Equal(t, sandboxtypes.StateRunning, stored.State,
		"the retry must not have killed the incarnation that reclaimed the ID")
}

// The tests above drive the pin through StartRemoving, which checks it in Go
// before doing any work. That check is a fast path, not the guarantee: the lock
// it holds excludes the other lock-taking operations but not Add, which is
// lockless, so a resume can install a new incarnation between the comparison
// and the write. Without an atomic guard the write would then overwrite the new
// live record with the stale one, and the removal's own cleanup would delete it.
//
// The guard therefore lives inside startTransitionScript, and these exercise it
// directly. There is no way to interleave an Add into the middle of a Lua
// script from a test — which is the property being relied on — so the script is
// driven with a record that has already moved on, standing in for the resume
// that would have landed in that window.

func transitionKeysFor(sbx sandboxtypes.Sandbox, transitionID string) []string {
	team := sbx.TeamID.String()

	return []string{
		getSandboxKey(team, sbx.SandboxID),
		getTransitionKey(team, sbx.SandboxID),
		getTransitionResultKey(team, sbx.SandboxID, transitionID),
	}
}

func TestStartTransitionScript_RefusesAStaleIncarnation(t *testing.T) {
	t.Parallel()

	storage, client := setupTestStorage(t)
	ctx := t.Context()

	sbx := createTestSandbox("sbx-cas-refuses")
	require.NoError(t, storage.Add(ctx, sbx))

	transitionID := uuid.NewString()
	keys := transitionKeysFor(sbx, transitionID)

	written, err := startTransitionScript.Run(ctx, client, keys,
		`{"executionID":"clobbered"}`, transitionID, 60, 60,
		uuid.NewString(), // the incarnation the caller pinned, no longer stored
	).Int64()
	require.NoError(t, err)
	assert.Equal(t, int64(0), written, "the script must refuse a stale pin")

	// Nothing may have been written: not the record, not the transition.
	stored, err := storage.Get(ctx, sbx.TeamID, sbx.SandboxID)
	require.NoError(t, err)
	assert.Equal(t, sbx.ExecutionID, stored.ExecutionID, "the live record must be untouched")
	assert.Equal(t, sandboxtypes.StateRunning, stored.State)
	assert.Zero(t, client.Exists(ctx, keys[1]).Val(), "a refused transition must not be started")
}

func TestStartTransitionScript_ProceedsOnTheMatchingIncarnation(t *testing.T) {
	t.Parallel()

	storage, client := setupTestStorage(t)
	ctx := t.Context()

	sbx := createTestSandbox("sbx-cas-proceeds")
	require.NoError(t, storage.Add(ctx, sbx))

	transitionID := uuid.NewString()
	keys := transitionKeysFor(sbx, transitionID)

	updated := sbx
	updated.State = sandboxtypes.StateKilling
	data, err := json.Marshal(updated)
	require.NoError(t, err)

	written, err := startTransitionScript.Run(ctx, client, keys,
		data, transitionID, 60, 60, sbx.ExecutionID,
	).Int64()
	require.NoError(t, err)
	assert.Equal(t, int64(1), written)

	stored, err := storage.Get(ctx, sbx.TeamID, sbx.SandboxID)
	require.NoError(t, err)
	assert.Equal(t, sandboxtypes.StateKilling, stored.State)
}

// TestStartTransitionScript_RefusesADeletedRecord covers the other way the pin
// can stop holding: the record is gone entirely rather than replaced. Writing
// then would resurrect a removed sandbox.
func TestStartTransitionScript_RefusesADeletedRecord(t *testing.T) {
	t.Parallel()

	storage, client := setupTestStorage(t)
	ctx := t.Context()

	sbx := createTestSandbox("sbx-cas-deleted")
	require.NoError(t, storage.Add(ctx, sbx))
	require.NoError(t, storage.Remove(ctx, sbx.TeamID, sbx.SandboxID))

	transitionID := uuid.NewString()
	keys := transitionKeysFor(sbx, transitionID)

	written, err := startTransitionScript.Run(ctx, client, keys,
		`{"executionID":"resurrected"}`, transitionID, 60, 60, sbx.ExecutionID,
	).Int64()
	require.NoError(t, err)
	assert.Equal(t, int64(0), written)
	assert.Zero(t, client.Exists(ctx, keys[0]).Val(), "a refused transition must not resurrect the record")
}

// TestStartTransitionScript_UnpinnedWritesUnconditionally keeps the guard
// opt-in at the script level too: every existing caller passes no pin and must
// be unaffected.
func TestStartTransitionScript_UnpinnedWritesUnconditionally(t *testing.T) {
	t.Parallel()

	storage, client := setupTestStorage(t)
	ctx := t.Context()

	sbx := createTestSandbox("sbx-cas-unpinned")
	require.NoError(t, storage.Add(ctx, sbx))

	transitionID := uuid.NewString()
	keys := transitionKeysFor(sbx, transitionID)

	updated := sbx
	updated.State = sandboxtypes.StateKilling
	data, err := json.Marshal(updated)
	require.NoError(t, err)

	written, err := startTransitionScript.Run(ctx, client, keys,
		data, transitionID, 60, 60, "",
	).Int64()
	require.NoError(t, err)
	assert.Equal(t, int64(1), written)
}

// TestStartRemoving_NoExecutionPinRemovesWhateverIsStored keeps the guard
// opt-in: callers acting on user intent or a fresh read must not be forced to
// supply an execution ID.
func TestStartRemoving_NoExecutionPinRemovesWhateverIsStored(t *testing.T) {
	t.Parallel()

	storage, _ := setupTestStorage(t)

	sbx := createTestSandbox("sbx-unpinned")
	require.NoError(t, storage.Add(t.Context(), sbx))

	_, _, finish, err := storage.StartRemoving(t.Context(), sbx.TeamID, sbx.SandboxID, sandboxtypes.RemoveOpts{
		Action: sandboxtypes.StateActionKill,
		Reason: sandboxtypes.KillReasonRequest,
	})
	require.NoError(t, err)
	require.NotNil(t, finish)
	finish(t.Context(), nil)

	stored, err := storage.Get(t.Context(), sbx.TeamID, sbx.SandboxID)
	require.NoError(t, err)
	assert.Equal(t, sandboxtypes.StateKilling, stored.State)
}

package redis

import (
	"context"
	"encoding/json"
	"fmt"
	"testing"
	"time"

	"github.com/google/uuid"
	"github.com/redis/go-redis/v9"
	"github.com/stretchr/testify/require"
	sdkmetric "go.opentelemetry.io/otel/sdk/metric"
	"go.opentelemetry.io/otel/sdk/metric/metricdata"

	"github.com/e2b-dev/infra/packages/api/internal/sandbox/sandboxtypes"
	redis_utils "github.com/e2b-dev/infra/packages/shared/pkg/redis"
	"github.com/e2b-dev/infra/packages/shared/pkg/telemetry"
)

// makeIndexedSandbox builds a running sandbox fixture with explicit lifecycle
// timestamps for expiration index tests.
func makeIndexedSandbox(teamID uuid.UUID, sandboxID, executionID string, startTime, endTime time.Time) sandboxtypes.Sandbox {
	return sandboxtypes.Sandbox{
		SandboxID:         sandboxID,
		TemplateID:        "test-template",
		ClientID:          "test-client",
		TeamID:            teamID,
		ExecutionID:       executionID,
		StartTime:         startTime,
		EndTime:           endTime,
		MaxInstanceLength: 24 * time.Hour,
		State:             sandboxtypes.StateRunning,
	}
}

func requireMemberScore(t *testing.T, client redis.UniversalClient, member string, wantScore float64) {
	t.Helper()

	score, err := client.ZScore(t.Context(), globalExpirationSet, member).Result()
	require.NoError(t, err)
	require.InDelta(t, wantScore, score, 0.5)
}

