package clickhouse_test

import (
	"io/fs"
	"path/filepath"
	"testing"

	"github.com/stretchr/testify/require"

	"github.com/e2b-dev/infra/packages/clickhouse"
)

// The embed pattern names *.sql directly under migrations/, which is also the
// whole set a goose provider over the directory applies. A file the pattern
// missed would be applied by the migrator and skipped by every binary; this
// keeps the two sets equal.
func TestMigrationsEmbedsTheDirectory(t *testing.T) {
	t.Parallel()

	paths, err := filepath.Glob(filepath.Join("migrations", "*.sql"))
	require.NoError(t, err)
	onDisk := make([]string, 0, len(paths))
	for _, path := range paths {
		onDisk = append(onDisk, filepath.Base(path))
	}

	embedded, err := fs.Glob(clickhouse.Migrations(), "*")
	require.NoError(t, err)

	require.NotEmpty(t, onDisk)
	require.ElementsMatch(t, onDisk, embedded)
}

package dockerhub

import (
	"testing"

	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"
)

func TestNewAzureRemoteRepositoryValidatesURL(t *testing.T) {
	t.Parallel()

	// A malformed repository URL must fail at construction with a config
	// error, not at the first pull as an opaque token-exchange failure
	// against a host like "https:".
	for _, tt := range []struct {
		name    string
		url     string
		wantErr string
	}{
		{name: "scheme prefix rejected", url: "https://myregistry.azurecr.io/dockerhub", wantErr: "invalid Azure remote repository URL"},
		{name: "empty rejected", url: "", wantErr: "invalid Azure remote repository URL"},
		{name: "registry-less path rejected", url: "dockerhub", wantErr: "invalid Azure remote repository URL"},
	} {
		t.Run(tt.name, func(t *testing.T) {
			t.Parallel()

			_, err := NewAzureRemoteRepository(t.Context(), tt.url)
			require.Error(t, err)
			assert.Contains(t, err.Error(), tt.wantErr)
		})
	}
}

func TestNewAzureRemoteRepositoryAcceptsRegistryHostURL(t *testing.T) {
	t.Parallel()

	// The complementary case, so the validation cannot pass by rejecting
	// everything.
	r, err := NewAzureRemoteRepository(t.Context(), "myregistry.azurecr.io/dockerhub")
	require.NoError(t, err)
	require.NotNil(t, r)
}

package dockerhub

import (
	"testing"
)

func TestRemoveRegistryFromTag(t *testing.T) {
	t.Parallel()
	tests := []struct {
		name    string
		tag     string
		want    string
		wantErr bool
	}{
		{
			name:    "tag with registry prefix",
			tag:     "docker.io/library/ubuntu:latest",
			want:    "library/ubuntu:latest",
			wantErr: false,
		},
		{
			name:    "tag without registry",
			tag:     "ubuntu:latest",
			want:    "library/ubuntu:latest",
			wantErr: false,
		},
		{
			name:    "tag without registry",
			tag:     "index.docker.io/ubuntu:latest",
			want:    "library/ubuntu:latest",
			wantErr: false,
		},
		{
			name:    "tag with custom registry",
			tag:     "gcr.io/my-project/my-image:v1.0.0",
			want:    "my-project/my-image:v1.0.0",
			wantErr: false,
		},
		{
			name:    "tag with port in registry",
			tag:     "localhost:5000/my-image:latest",
			want:    "my-image:latest",
			wantErr: false,
		},
		{
			name:    "invalid tag format",
			tag:     ":::invalid",
			want:    "",
			wantErr: true,
		},
		{
			name:    "empty tag",
			tag:     "",
			want:    "",
			wantErr: true,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			t.Parallel()
			got, err := removeRegistryFromTag(tt.tag)
			if (err != nil) != tt.wantErr {
				t.Errorf("removeRegistryFromTag() error = %v, wantErr %v", err, tt.wantErr)

				return
			}
			if got != tt.want {
				t.Errorf("removeRegistryFromTag() = %v, want %v", got, tt.want)
			}
		})
	}
}

package tracing

import (
	"io/fs"
	"os"
	"syscall"
	"testing"

	"github.com/stretchr/testify/assert"
)

func TestIsUserError(t *testing.T) {
	t.Parallel()

	testCases := map[string]struct {
		err      error
		expected bool
	}{
		"os.ErrNotExist": {
			err:      os.ErrNotExist,
			expected: true,
		},
		"os.ErrExist": {
			err:      os.ErrExist,
			expected: true,
		},
		"fs.ErrNotExist": {
			err:      fs.ErrNotExist,
			expected: true,
		},
		"*fs.PathError(no such file)": {
			err:      &fs.PathError{Op: "open", Path: "no_such_file", Err: fs.ErrNotExist},
			expected: true,
		},
		"syscall.EEXIST": {
			err:      syscall.EEXIST,
			expected: true,
		},
		"syscall.ENOEXIST": {
			err:      syscall.ENOENT,
			expected: true,
		},
		"other error": {
			err:      syscall.EACCES,
			expected: false,
		},
	}

	for name, tc := range testCases {
		t.Run(name, func(t *testing.T) {
			t.Parallel()

			actual := isUserError(tc.err)
			assert.Equal(t, tc.expected, actual)
		})
	}
}
